/* Tablekeep Player & Homebrew Studio v0.4.0
 * Loads the supplied 2014 and 2024 JSON catalog files directly, without rewriting them.
 */
const APP_KEY = 'tablekeep.player-homebrew.v3';
const EDITIONS = ['2014', '2024'];
const CATEGORIES = [
  ['classes', 'Classes', '♜'], ['races', 'Species & races', '♙'], ['subclasses', 'Subclasses', '✧'],
  ['backgrounds', 'Backgrounds', '▤'], ['feats', 'Feats', '✦'], ['spells', 'Spells', '✧'],
  ['items', 'Equipment', '◇'], ['magicitems', 'Magic items', '✥'], ['masteries', 'Weapon masteries', '⚔'],
  ['monsters', 'Monster index', '♞']
];
const DB_FILES = ['backgrounds', 'classes', 'feats', 'items', 'magicitems', 'races', 'spells', 'masteries'];
const SKILLS = ['Acrobatics','Animal Handling','Arcana','Athletics','Deception','History','Insight','Intimidation','Investigation','Medicine','Nature','Perception','Performance','Persuasion','Religion','Sleight of Hand','Stealth','Survival'];
const BUILDER_STEPS = [
  ['class','Choose a class','Your character’s core training and role.'],
  ['race','Choose a species','Heritage, traits, size, speed, and languages.'],
  ['subclass','Choose a subclass','A specialisation unlocked by your class.'],
  ['abilities','Set ability scores','Assign the six abilities for your character.'],
  ['background','Choose a background','History, proficiencies, equipment, and features.'],
  ['skills','Choose skills','Select skills that fit your character.'],
  ['feats','Choose feats','Add special talents and improvements.'],
  ['equipment','Choose equipment','Pick weapons, armour, and adventuring gear.'],
  ['spells','Choose spells','Browse spells from the selected ruleset.'],
  ['details','Character details','Name your character and save the build.']
];
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titleCase = s => String(s).replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase()).replace(/[_-]/g,' ');
const shortText = (v, n=150) => { const s=String(v ?? '').replace(/\s+/g,' ').trim(); return s.length>n ? s.slice(0,n-1)+'…' : s; };
const idOf = x => String(x?.id ?? x?.key ?? x?.name ?? '');
const nameOf = x => String(x?.name ?? x?.title ?? x?.label ?? 'Untitled entry');
const state = loadState();
const db = { '2014': {}, '2024': {} };
let activePage = 'home';
let activeEdition = state.edition || '2014';
let selectedCharacterId = state.selectedCharacterId || null;
let builder = freshBuilder();
let libraryCategory = 'classes';
let libraryPage = 1;
let libraryQuery = '';
let currentDetail = null;
let owlBear = null;
let catalogReady = false;
const PAGE_SIZE = 36;
const catalogLoadProgress = {total:16,done:0,last:'Preparing content catalogue…'};

function freshBuilder(){ return {step:0, classId:'', raceId:'', subraceId:'', subclassId:'', backgroundId:'', abilities:{STR:15,DEX:14,CON:13,INT:12,WIS:10,CHA:8}, abilityMethod:'standard', skills:[], backgroundSkills:[], feats:[], grantedFeats:{}, equipment:[], spells:[], equipmentChoices:{}, asiChoices:{race:[],background:[]}, search:{}, name:'', level:1, notes:''}; }
function loadState(){ try { return {edition:'2014',characters:[],homebrew:[],combatants:[],diceHistory:[],...JSON.parse(localStorage.getItem(APP_KEY)||'{}')}; } catch { return {edition:'2014',characters:[],homebrew:[],combatants:[],diceHistory:[]}; } }
function saveState(){ try { localStorage.setItem(APP_KEY,JSON.stringify(state)); updateBadges(); } catch(e){ toast('Local storage is full. Export your data before continuing.','warn'); } }
function toast(message,type='success'){ const host=$('#toastRegion'); const node=document.createElement('div'); node.className=`toast ${type}`; node.textContent=message; host.append(node); setTimeout(()=>node.remove(),3200); }
function records(edition=activeEdition, category){ const list=db[edition]?.[category] || []; return list; }
function allRecords(edition=activeEdition){ return CATEGORIES.filter(([key])=>key!=='subclasses'&&key!=='monsters').flatMap(([key])=>records(edition,key)); }
function findRecord(category,id,edition=activeEdition){ return records(edition,category).find(x=>idOf(x)===String(id)||nameOf(x)===String(id)); }
function subclassesForCurrentClass(){ const cls=findRecord('classes',builder.classId); const subs=Array.isArray(cls?.subclassOptions)&&cls.subclassOptions.length?cls.subclassOptions:(Array.isArray(cls?.subclasses)?cls.subclasses:[]); return subs.map((x,i)=>typeof x==='string'?{id:`${builder.classId}-sub-${i}`,name:x,source:cls?.source||'',description:''}:{...x,id:x.id??`${builder.classId}-sub-${i}`}); }
function getCountSummary(edition=activeEdition){ return CATEGORIES.filter(([k])=>k!=='subclasses'&&k!=='monsters').reduce((a,[k])=>a+(records(edition,k).length),0); }
async function fetchJSON(path){
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);
  try {
    const r = await fetch(path, { cache: 'default', signal: controller.signal });
    if (!r.ok) throw new Error(`${r.status} ${path}`);
    return await r.json();
  } catch (error) {
    if (error?.name === 'AbortError') throw new Error(`Timed out while loading ${path} (15 seconds)`);
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}
const catalogLoadErrors = [];
async function loadDatabase(){
  const jobs=[];
  catalogLoadErrors.length = 0;
  catalogLoadProgress.done=0;catalogLoadProgress.last='Starting catalogue files…';
  for(const edition of EDITIONS){
    db[edition]={};
    for(const file of DB_FILES){
      if(file==='masteries'&&edition==='2014') continue;
      jobs.push((async()=>{
        const path = `./data/${edition}/${file}.json`;
        try {
          const payload = await fetchJSON(path);
          if (!Array.isArray(payload)) throw new Error('Expected a JSON array at the file root');
          db[edition][file] = payload;
        } catch(error) {
          db[edition][file] = [];
          catalogLoadErrors.push(`${edition}/${file}.json: ${error.message}`);
          console.warn('Could not load content file:', path, error);
        } finally {
          catalogLoadProgress.done++;catalogLoadProgress.last=path.replace('./data/','');
          if(!catalogReady&&$('#pageRoot'))$('#pageRoot').innerHTML=renderPage(activePage);
        }
      })());
    }
  }
  jobs.push((async()=>{
    const path = './data/catalogs/monsters.json';
    try {
      const payload = await fetchJSON(path);
      if (!Array.isArray(payload.items)) throw new Error('Expected an items array in the monster index');
      db['2014'].monsters = payload.items;
      db['2024'].monsters = payload.items;
    } catch(error) {
      db['2014'].monsters = [];
      db['2024'].monsters = [];
      catalogLoadErrors.push(`catalogs/monsters.json: ${error.message}`);
      console.warn('Could not load monster index:', path, error);
    } finally {
      catalogLoadProgress.done++;catalogLoadProgress.last='catalogs/monsters.json';
      if(!catalogReady&&$('#pageRoot'))$('#pageRoot').innerHTML=renderPage(activePage);
    }
  })());
  await Promise.all(jobs);
  catalogReady = true;
  updateBadges();
}
function updateBadges(){ $('#characterCount').textContent=state.characters.length; $('#homebrewCount').textContent=state.homebrew.length; }
function pageTitle(key){ return ({home:'Home',characters:'My characters',builder:'Character builder',sheet:'Character sheet',homebrew:'Homebrew studio',library:'Content library',table:'DM toolkit',dice:'Dice roller',settings:'Settings & data'})[key]||'Home'; }
function go(page){ activePage=page; $$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page)); $('#breadcrumbCurrent').textContent=pageTitle(page); $('#pageRoot').innerHTML=renderPage(page); closeSidebar(); if(page==='library') renderLibraryList(); if(page==='builder') renderBuilderStep(); if(page==='sheet') renderSheet(); if(page==='table') renderTable(); window.scrollTo({top:0,behavior:'smooth'}); }
function closeSidebar(){ $('#sidebar').classList.remove('open'); $('#mobileScrim').classList.remove('show'); }
function pageShell(eyebrow,title,sub,actions=''){return `<div class="page-heading heading-with-actions"><div><div class="eyebrow"><span class="eyebrow-line"></span>${eyebrow}</div><h1>${title}</h1><p class="page-subtitle">${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function renderPage(page){
  if(!catalogReady){const pct=Math.round(catalogLoadProgress.done/catalogLoadProgress.total*100);return `<div class="loading-panel"><div class="spinner"></div><h2>Opening your library…</h2><p>Loading original 2014 and 2024 content files.</p><div class="catalog-progress"><div><span>${catalogLoadProgress.done} / ${catalogLoadProgress.total} files loaded</span><b>${pct}%</b></div><i><span style="width:${pct}%"></span></i><small>Latest: ${esc(catalogLoadProgress.last)}</small></div></div>`;}
  return ({home:renderHome,characters:renderCharacters,builder:renderBuilder,sheet:renderSheet,homebrew:renderHomebrew,library:renderLibrary,table:renderTable,dice:renderDice,settings:renderSettings}[page]||renderHome)();
}
function renderHome(){
 const total14=getCountSummary('2014'), total24=getCountSummary('2024');
 const recent=[['classes','classes'],['races','species'],['spells','spells'],['feats','feats']].map(([k,l])=>({key:k,label:l,count:records(activeEdition,k).length}));
 return `${pageShell('PLAYER & CREATOR WORKSPACE','Your next story <em>starts here.</em>','Create a hero, shape a world, or explore the rules. Your character and homebrew work are saved locally.',`<button class="button button-quiet" data-go="library">Explore content</button><button class="button button-primary" data-go="builder">＋ Create character</button>`)}
 <section class="welcome-hero"><div class="welcome-copy"><div class="hero-kicker"><span class="hero-kicker-dot"></span> YOUR ADVENTURE WORKSPACE</div><h2>Every great story<br>begins with a <em>character.</em></h2><p>Build characters from level 1 to 20, create original homebrew content, and bring your creations to the table.</p><div class="hero-cta"><button class="button button-primary" data-go="builder">Start character builder <span>↗</span></button><button class="button button-glass" data-go="homebrew">Open homebrew studio</button></div><div class="hero-meta"><span>✦ 2014 & 2024 rulesets</span><span>♙ Local character vault</span><span>⚗ Custom creations</span></div></div><div class="hero-illustration" aria-hidden="true"><div class="sigil sigil-a"></div><div class="sigil sigil-b"></div><div class="rune-orbit"></div><div class="hero-crystal">✦</div><div class="hero-illustration-label">FORGED BY YOU · PLAYED TOGETHER</div></div></section>
 <div class="metric-grid"><article class="metric-card"><div class="metric-top"><span>2014 CONTENT</span><span class="metric-icon icon-gold">◈</span></div><div class="metric-value">${total14.toLocaleString()}</div><div class="metric-foot">Records across 7 libraries</div></article><article class="metric-card"><div class="metric-top"><span>2024 CONTENT</span><span class="metric-icon icon-blue">✧</span></div><div class="metric-value">${total24.toLocaleString()}</div><div class="metric-foot">Records across 8 libraries</div></article><article class="metric-card"><div class="metric-top"><span>MY CHARACTERS</span><span class="metric-icon icon-green">♙</span></div><div class="metric-value">${state.characters.length}</div><div class="metric-foot">Saved in this browser</div></article><article class="metric-card"><div class="metric-top"><span>MY HOMEBREW</span><span class="metric-icon icon-violet">⚗</span></div><div class="metric-value">${state.homebrew.length}</div><div class="metric-foot">Custom creations</div></article></div>
 <div class="section-heading"><div><div class="eyebrow">CHOOSE YOUR PATH</div><h2>Make something <em>legendary.</em></h2></div><span class="section-note">BUILT FOR PLAYERS & CREATORS</span></div>
 <div class="feature-grid"><button class="feature-card feature-character" data-go="builder"><span class="feature-icon">♙</span><span class="feature-kicker">PLAYER STUDIO</span><strong>Character builder</strong><small>Choose class, species, abilities, background, feats, gear, and spells.</small><b>Build a character <i>↗</i></b></button><button class="feature-card feature-homebrew" data-go="homebrew"><span class="feature-icon">⚗</span><span class="feature-kicker">CREATOR STUDIO</span><strong>Homebrew workshop</strong><small>Create classes, subclasses, species, feats, spells, backgrounds, and items.</small><b>Create homebrew <i>↗</i></b></button><button class="feature-card feature-library" data-go="library"><span class="feature-icon">◈</span><span class="feature-kicker">CONTENT LIBRARY</span><strong>Explore the compendium</strong><small>Search all imported data from both rulesets, including full descriptions and features.</small><b>Browse content <i>↗</i></b></button></div>
 <div class="content-grid overview-lower"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">YOUR CREATIONS</div><h3>Recent characters</h3></div><button class="text-button" data-go="characters">View all ↗</button></div>${state.characters.length?`<div class="mini-character-list">${state.characters.slice(-3).reverse().map(characterRow).join('')}</div>`:`<div class="empty-state compact"><span>♙</span><strong>Your character vault is waiting.</strong><p>Start with a class and species. Your build stays on this device.</p><button class="button button-outline" data-go="builder">Create first character</button></div>`}</section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">CONTENT LOADED</div><h3>${activeEdition} ruleset</h3></div><span class="edition-chip">${activeEdition}</span></div><div class="content-count-list">${recent.map(x=>`<button class="count-row" data-library="${x.key}"><span>${titleCase(x.label)}</span><b>${x.count.toLocaleString()}</b><i>↗</i></button>`).join('')}<button class="count-row" data-library="magicitems"><span>Magic items</span><b>${records(activeEdition,'magicitems').length.toLocaleString()}</b><i>↗</i></button></div></section></div>
 <div class="bottom-note"><span>✦</span><span><strong>Original content files are preserved.</strong> The app reads JSON directly from <code>data/2014/</code> and <code>data/2024/</code>; you do not need to reshape or re-enter the catalogue data.</span><button data-go="settings">Data details ↗</button></div>`;
}
function characterRow(c){return `<button class="character-row" data-open-character="${esc(c.id)}"><span class="avatar">${esc((c.name||'??').slice(0,2).toUpperCase())}</span><span class="character-row-main"><strong>${esc(c.name)}</strong><small>Level ${c.level||1} · ${esc(c.className||'Adventurer')} · ${esc(c.speciesName||'Species not set')}</small></span><b>↗</b></button>`;}
function renderCharacters(){return `${pageShell('PLAYER STUDIO','Your characters <em>& legends.</em>','Manage your saved characters and pick up where your last adventure left off.',`<button class="button button-outline" data-action="import-character">Import character</button><button class="button button-primary" data-go="builder">＋ New character</button>`)}<div class="character-toolbar"><input type="file" id="importCharacterFile" accept="application/json,.json" hidden><div class="toolbar-copy"><strong>${state.characters.length} saved character${state.characters.length===1?'':'s'}</strong><span>Private to this browser until you export or share them.</span></div><button class="button button-outline" data-action="export-characters">Export characters</button></div>${state.characters.length?`<div class="character-grid">${state.characters.map(c=>`<article class="character-card"><div class="character-card-top"><div class="avatar avatar-gold">${esc((c.name||'??').slice(0,2).toUpperCase())}</div><span class="edition-chip">${esc(c.edition||activeEdition)}</span></div><h3>${esc(c.name)}</h3><p>${esc(c.speciesName||'Unchosen species')} · ${esc(c.className||'Adventurer')}</p><div class="character-card-stats"><span>LEVEL <b>${c.level||1}</b></span><span>HP <b>${c.hp??0}/${c.maxHp??0}</b></span><span>AC <b>${c.ac??'—'}</b></span></div><div class="character-card-actions"><button class="button button-primary button-small" data-open-character="${esc(c.id)}">Open sheet</button><button class="button button-quiet button-small" data-edit-character="${esc(c.id)}">Edit build</button><button class="icon-button danger-icon" title="Delete character" data-delete-character="${esc(c.id)}">×</button></div></article>`).join('')}</div>`:`<div class="empty-large"><div class="empty-emblem">♙</div><h2>No characters <em>yet.</em></h2><p>Create your first character with the guided builder. Class, species, background, feats, equipment, and spells are loaded from the selected ruleset.</p><button class="button button-primary" data-go="builder">Create a character <span>↗</span></button></div>`}`;}
function builderClass(){return findRecord('classes',builder.classId)||null;}
function builderRace(){return findRecord('races',builder.raceId)||null;}
function builderBackground(){return findRecord('backgrounds',builder.backgroundId)||null;}
function builderSubrace(){const r=builderRace();return (r?.subraces||[]).find(x=>idOf(x)===builder.subraceId)||null;}
function skillChoicesForClass(){const p=builderClass()?.proficiencies?.skills||{};return {count:Number(p.choose||0),from:Array.isArray(p.from)?p.from:[]};}
function fixedBackgroundSkills(){const b=builderBackground();const v=b?.skillProficiencies||[];return Array.isArray(v)?v:[];}
function backgroundSkillChoices(){const b=builderBackground();return Array.isArray(b?.skillChoices)?b.skillChoices:[];}
function pointBuyCost(score){return ({8:0,9:1,10:2,11:3,12:4,13:5,14:7,15:9})[Number(score)]??99;}
function pointBuySpent(){return Object.values(builder.abilities).reduce((n,v)=>n+pointBuyCost(v),0);}
function abilityBonuses(){const r=builderSubrace()||builderRace(),b=builderBackground();const out={str:0,dex:0,con:0,int:0,wis:0,cha:0};for(const src of [r?.asi]){if(src&&typeof src==='object'&&!Array.isArray(src))for(const [k,v] of Object.entries(src))if(k.toLowerCase() in out&&typeof v==='number')out[k.toLowerCase()]+=v;}const rc=r?.asiChoice;if(rc&&Array.isArray(builder.asiChoices?.race)){const amount=Number(rc.amount||1);builder.asiChoices.race.slice(0,Number(rc.count||0)).forEach(k=>{if(k in out)out[k]+=amount;});}const allowed=Array.isArray(b?.abilityScores)?b.abilityScores.map(x=>String(x).toLowerCase()):[];const picks=builder.asiChoices?.background||[];if(allowed.length&&picks[0]&&allowed.includes(picks[0]))out[picks[0]]+=2;if(allowed.length&&picks[1]&&allowed.includes(picks[1])&&picks[1]!==picks[0])out[picks[1]]+=1;return out;}
function featGrantChoices(){const out=[],b=builderBackground(),r=builderSubrace()||builderRace();if(activeEdition==='2024'&&b?.feat&&!b.feat.featId&&!b.feat.id)out.push({key:'background',label:`Background: ${b.name}`,category:b.feat.category||null});for(let i=0;i<(r?.featGrants||[]).length;i++){const g=r.featGrants[i]||{};if(!(g.featId||g.id||g.name))out.push({key:`species-${i}`,label:`Species: ${r.name}`,category:g.category||null});}return out;}
function grantedFeatRecords(){const out=[];const b=builderBackground();if(activeEdition==='2024'&&b?.feat){const id=b.feat.featId||b.feat.id;const f=id?findRecord('feats',id):findRecord('feats',builder.grantedFeats.background);if(f)out.push({...f,__grantSource:`Background: ${b.name}`});}const r=builderSubrace()||builderRace();for(let i=0;i<(r?.featGrants||[]).length;i++){const g=r.featGrants[i]||{},id=g.featId||g.id||g.name||builder.grantedFeats[`species-${i}`];const f=id?findRecord('feats',id):null;if(f)out.push({...f,__grantSource:`Species: ${r.name}`});}return out;}
function builderChoices(category, selectedIds=[]){const all=records(activeEdition,category);const q=(builder.search?.[category]||'').trim().toLowerCase();const filtered=q?all.filter(x=>JSON.stringify(x).toLowerCase().includes(q)):all;const visible=filtered.slice(0,48);return `<div class="builder-choice-tools"><input type="search" data-builder-search="${category}" value="${esc(builder.search?.[category]||'')}" placeholder="Search ${titleCase(category)}…"><span>${filtered.length.toLocaleString()} matches · showing ${visible.length}</span></div><div class="choice-grid">${visible.map(item=>{const id=idOf(item),on=selectedIds.includes(id);return `<button type="button" class="choice-card ${on?'selected':''}" data-choice="${category}" data-id="${esc(id)}" aria-pressed="${on}"><span class="choice-check">${on?'✓':'＋'}</span><strong>${esc(nameOf(item))}</strong><small>${esc(shortText(item.description||item.source||item.category||item.kind||'',115))}</small>${item.source?`<span class="choice-source">${esc(item.source)}</span>`:''}</button>`;}).join('')||'<div class="empty-state">No matching content.</div>'}</div>`;}
function renderOptionGroups(owner,groups){if(!Array.isArray(groups)||!groups.length)return '<p class="field-hint">No structured equipment choices are listed for this entry.</p>';return `<div class="builder-option-groups">${groups.map((g,i)=>{const key=g.id||`${owner}-${i}`,opts=g.options||[];if(!g.choice&&opts.length<=1)return `<div class="builder-option-group"><strong>${esc(g.prose||opts[0]?.label||'Included equipment')}</strong><small>Included automatically</small></div>`;return `<fieldset class="builder-option-group"><legend>${esc(g.prose||`Choose option ${i+1}`)}</legend>${opts.map((o,j)=>{const val=`${key}:${o.key??j}`;if(builder.equipmentChoices[key]===undefined)builder.equipmentChoices[key]=String(o.key??j);const checked=builder.equipmentChoices[key]===String(o.key??j);return `<label class="builder-option"><input type="radio" name="${esc(key)}" data-builder-option="${esc(key)}" value="${esc(o.key??j)}" ${checked?'checked':''}><span><b>${esc(o.label||o.key||`Option ${j+1}`)}</b><small>${(o.items||[]).map(it=>`${esc(it.name||it.label||it.any||'Item')}${it.quantity>1?` ×${it.quantity}`:''}`).join(' · ')||'Gold or custom choice'}${o.gold?` · ${o.gold} gp`:''}</small></span></label>`;}).join('')}</fieldset>`;}).join('')}</div>`;}
function renderBuilderEquipment(){const cls=builderClass(),bg=builderBackground();return `<section class="builder-rule-card"><div class="eyebrow">CLASS STARTING EQUIPMENT</div><h3>${esc(cls?.name||'Choose a class first')}</h3>${renderOptionGroups(`class-${builder.classId}`,cls?.startingEquipmentOptions||[])}</section><section class="builder-rule-card"><div class="eyebrow">BACKGROUND EQUIPMENT</div><h3>${esc(bg?.name||'Choose a background first')}</h3>${renderOptionGroups(`background-${builder.backgroundId}`,bg?.equipmentOptions||[])}</section><p class="field-hint">Equipment choices now follow the selected class and background. You can review the included items before saving.</p>`;}
function renderBuilderSkills(){const cls=builderClass(),bg=builderBackground(),fixed=fixedBackgroundSkills(),bgGroups=backgroundSkillChoices(),spec=skillChoicesForClass(),auto=new Set(fixed);const available=spec.from.length?spec.from:SKILLS;const bgPicked=new Set(builder.backgroundSkills.flat());const selected=builder.skills.filter(x=>available.includes(x)&&!auto.has(x)&&!bgPicked.has(x));return `<div class="builder-rule-card"><div class="eyebrow">BACKGROUND PROFICIENCIES</div><h3>${esc(bg?.name||'Choose a background')}</h3><div class="tag-list">${fixed.map(x=>`<span class="tag-locked">✓ ${esc(x)} · Background</span>`).join('')||'<span class="muted-copy">No fixed background skills selected.</span>'}</div>${bgGroups.map((g,i)=>{const from=Array.isArray(g.from)&&g.from.length?g.from:SKILLS,chosen=builder.backgroundSkills[i]||[];return `<div class="builder-rule-card"><div class="eyebrow">BACKGROUND SKILL CHOICE</div><h3>${esc(g.text||`Choose ${g.choose||1} skill(s)`)}</h3><div class="skill-grid">${from.map(skill=>`<label class="skill-check ${chosen.includes(skill)?'checked':''}"><input type="checkbox" data-background-skill="${i}" value="${esc(skill)}" ${chosen.includes(skill)?'checked':''}><span>${esc(skill)}</span></label>`).join('')}</div><small class="field-hint">Selected: ${chosen.length} / ${Number(g.choose||1)}</small></div>`;}).join('')}</div><div class="builder-rule-card"><div class="eyebrow">CLASS SKILL CHOICES</div><h3>Choose ${spec.count||0} skill${spec.count===1?'':'s'} from ${esc(cls?.name||'your class')}</h3><p class="field-hint">Select up to ${spec.count||0} proficiencies from the class list. Skills already granted by your background cannot be selected twice.</p><div class="skill-grid">${available.map(skill=>{const on=selected.includes(skill),locked=auto.has(skill)||bgGroups.some((g,i)=>(builder.backgroundSkills[i]||[]).includes(skill));return `<label class="skill-check ${on||locked?'checked':''} ${locked?'locked':''}"><input type="checkbox" data-skill="${esc(skill)}" ${on||locked?'checked':''} ${locked||!spec.count?'disabled':''}><span>${esc(skill)}${locked?' · Background':''}</span></label>`;}).join('')}</div><small class="field-hint">Selected from class: ${selected.length} / ${spec.count||0}</small></div>`;}
function renderBuilderFeats(){const grants=grantedFeatRecords(),choices=featGrantChoices();const level=Number(builder.level||1);const grantUi=choices.map(g=>{const list=records(activeEdition,'feats').filter(f=>!g.category||String(f.category||'').toLowerCase()===String(g.category).toLowerCase());return `<div class="builder-rule-card"><div class="eyebrow">SPECIES / BACKGROUND FEAT CHOICE</div><h3>${esc(g.label)}${g.category?` · ${esc(g.category)}`:''}</h3><div class="choice-grid">${list.slice(0,100).map(f=>{const id=idOf(f),on=builder.grantedFeats[g.key]===id;return `<button type="button" class="choice-card ${on?'selected':''}" data-granted-feat="${esc(g.key)}" data-id="${esc(id)}"><span class="choice-check">${on?'✓':'＋'}</span><strong>${esc(f.name)}</strong><small>${esc(shortText(f.description||f.prerequisite||'',105))}</small><span class="choice-source">${esc(f.source||'')}</span></button>`;}).join('')}</div></div>`;}).join('');return `<div class="builder-rule-card"><div class="eyebrow">AUTOMATIC FEAT GRANTS</div><h3>Granted by your choices</h3>${grants.length?grants.map(f=>`<div class="granted-feat"><strong>${esc(f.name)}</strong><span>${esc(f.__grantSource)}</span><p>${esc(shortText(f.description,220))}</p></div>`):'<p class="field-hint">No fixed feat grant has been selected by your species or background yet.</p>'}</div>${grantUi}${level>=4?`<div class="builder-rule-card"><div class="eyebrow">OPTIONAL LEVEL FEAT</div><h3>Choose a feat available at level ${level}</h3>${builderChoices('feats',builder.feats)}</div>`:`<div class="builder-rule-card"><div class="eyebrow">FEAT AVAILABILITY</div><h3>No optional feat at level ${level}</h3><p class="field-hint">Optional feat selection appears from level 4. Any species/background feat grants are shown above with their source.</p></div>`}`;}
function classProgressionRow(){const cls=builderClass();return (cls?.progression||[]).find(x=>Number(x.level)===Number(builder.level||1))||null;}
function maxSpellLevel(){const row=classProgressionRow(),slots=row?.slots||[];let max=0;slots.forEach((n,i)=>{if(Number(n)>0)max=i+1;});return row?max:1;}
function spellLimits(){const extras=classProgressionRow()?.extras||{};const pick=(keys)=>{for(const k of keys){const v=extras[k];if(v!==undefined){const m=String(v).match(/\d+/);if(m)return Number(m[0]);}}return null;};return {cantrips:pick(['Cantrips Known','Cantrips']),known:pick(['Spells Known','Prepared Spells','Prepared'])};}
function renderBuilderSpells(){const cls=builderClass(),casting=cls?.spellcasting;if(!casting)return `<div class="empty-state"><strong>${esc(cls?.name||'This class')} does not have spellcasting.</strong><p>Spell selection is hidden for non-spellcasting classes. Change class if you want to build a spellcaster.</p></div>`;const maxLevel=maxSpellLevel(),limits=spellLimits();const allowed=records(activeEdition,'spells').filter(sp=>Number(sp.level||0)<=maxLevel&&(!Array.isArray(sp.classes)||!sp.classes.length||sp.classes.some(c=>String(c).toLowerCase()===String(cls.name).toLowerCase())));const q=(builder.search?.spells||'').toLowerCase();const shown=allowed.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q)).slice(0,80);return `<div class="builder-rule-card"><div class="eyebrow">SPELLCASTING</div><h3>${esc(cls.name)} · ${esc(String(casting.ability||'').toUpperCase())} spellcasting</h3><p class="field-hint">Only spells associated with this class and spell levels available at level ${Number(builder.level||1)} (up to level ${maxLevel}) are shown. ${limits.cantrips!==null?`Cantrips: ${builder.spells.filter(id=>findRecord('spells',id)?.level===0).length}/${limits.cantrips}.`:''} ${limits.known!==null?`Known/prepared spell allowance: ${limits.known}.`:''}</p></div><div class="builder-choice-tools"><input type="search" data-builder-search="spells" value="${esc(builder.search?.spells||'')}" placeholder="Search eligible spells…"><span>${allowed.length} eligible · showing ${shown.length}</span></div><div class="choice-grid">${shown.map(sp=>{const id=idOf(sp),on=builder.spells.includes(id);return `<button type="button" class="choice-card ${on?'selected':''}" data-choice="spells" data-id="${esc(id)}"><span class="choice-check">${on?'✓':'＋'}</span><strong>${esc(sp.name)}</strong><small>${sp.level===0?'Cantrip':`Level ${sp.level}`} · ${esc(sp.school||'')}</small><span class="choice-source">${esc(sp.source||'')}</span></button>`;}).join('')||'<div class="empty-state">No eligible spells match your search.</div>'}</div>`;}
function renderASIChoices(){const r=builderSubrace()||builderRace(),b=builderBackground(),rc=r?.asiChoice,allowedBg=Array.isArray(b?.abilityScores)?b.abilityScores.map(x=>String(x).toLowerCase()):[];let html='';if(rc&&Number(rc.count||0)>0){const n=Number(rc.count||0),opts=['str','dex','con','int','wis','cha'];html+=`<div class="builder-rule-card"><div class="eyebrow">SPECIES ABILITY CHOICE</div><h3>Choose ${n} ability score${n===1?'':'s'} for +${Number(rc.amount||1)} each</h3><div class="skill-grid">${opts.map(k=>`<label class="skill-check ${(builder.asiChoices.race||[]).includes(k)?'checked':''}"><input type="checkbox" data-asi-choice="race" value="${k}" ${(builder.asiChoices.race||[]).includes(k)?'checked':''}><span>${k.toUpperCase()}</span></label>`).join('')}</div></div>`;}if(allowedBg.length){html+=`<div class="builder-rule-card"><div class="eyebrow">BACKGROUND ABILITY CHOICE</div><h3>Choose one ability for +2 and another for +1</h3><div class="skill-grid">${allowedBg.map(k=>`<label class="skill-check ${(builder.asiChoices.background||[]).includes(k)?'checked':''}"><input type="checkbox" data-asi-choice="background" value="${k}" ${(builder.asiChoices.background||[]).includes(k)?'checked':''}><span>${k.toUpperCase()}</span></label>`).join('')}</div></div>`;}return html;}
function stepContent(step){
 const key=step.key;
 if(key==='class') return `<div class="builder-rule-card builder-level-select"><div class="eyebrow">CHARACTER LEVEL</div><label class="form-field"><span>STARTING LEVEL</span><input id="builderLevel" type="number" min="1" max="20" value="${builder.level||1}"></label><p class="field-hint">Choose the level before selecting subclass features, feats, and spell options.</p></div>${builderChoices('classes',builder.classId?[builder.classId]:[])}`;
 if(key==='race'){const race=builderRace();return `${builderChoices('races',builder.raceId?[builder.raceId]:[])}${race&&race.subraces?.length?`<div class="builder-rule-card"><div class="eyebrow">SPECIES VARIANT</div><h3>Choose a ${esc(race.name)} lineage</h3><div class="choice-grid">${race.subraces.map(x=>`<button type="button" class="choice-card ${builder.subraceId===idOf(x)?'selected':''}" data-choice="subraces" data-id="${esc(idOf(x))}"><span class="choice-check">${builder.subraceId===idOf(x)?'✓':'＋'}</span><strong>${esc(x.name)}</strong><small>${esc(shortText((x.traits||[]).map(t=>t.text||t.name).join(' '),110))}</small><span class="choice-source">${esc(x.source||race.source||'')}</span></button>`).join('')}</div></div>`:''}${race?`<div class="builder-rule-card"><div class="eyebrow">SPECIES TRAITS</div><h3>${esc(race.name)} traits</h3><div class="trait-list">${(builderSubrace()?.traits||race.traits||[]).slice(0,12).map(t=>`<div><b>${esc(t.name||'Trait')}</b><p>${esc(shortText(t.text||t.description||'',260))}</p></div>`).join('')}</div></div>`:''}`;}
 if(key==='subclass'){const list=subclassesForCurrentClass();const unlock=Number(builderClass()?.subclassLevel||1);if(Number(builder.level||1)<unlock)return `<div class="empty-state"><strong>${esc(builderClass()?.subclassLabel||'Subclass')} unlocks at level ${unlock}.</strong><p>Your current level is ${Number(builder.level||1)}. You can continue without choosing a subclass.</p></div>`;return list.length?`<div class="builder-rule-card"><div class="eyebrow">${esc(builderClass()?.subclassLabel||'SUBCLASS')}</div><h3>Choose your ${esc(builderClass()?.subclassLabel||'subclass')}</h3><p class="field-hint">${builderClass()?.subclassLevel?`Unlocked at class level ${builderClass().subclassLevel}.`:''} Options are drawn from the selected class.</p><div class="choice-grid">${list.map(x=>`<button type="button" class="choice-card ${builder.subclassId===idOf(x)?'selected':''}" data-choice="subclasses" data-id="${esc(idOf(x))}"><span class="choice-check">${builder.subclassId===idOf(x)?'✓':'＋'}</span><strong>${esc(nameOf(x))}</strong><small>${esc(shortText(x.description||'',115))}</small><span class="choice-source">${esc(x.source||'')}</span></button>`).join('')}</div></div>`:`<div class="empty-state">Choose a class with subclass options first. You can continue without a subclass.</div>`;}
 if(key==='abilities'){const bonus=abilityBonuses(),spent=pointBuySpent();return `<div class="builder-rule-card"><div class="eyebrow">ABILITY SCORES</div><h3>Set your six abilities</h3><div class="ability-methods"><button type="button" class="button ${builder.abilityMethod==='standard'?'button-primary':'button-outline'} button-small" data-ability-mode="standard">Standard array</button><button type="button" class="button ${builder.abilityMethod==='point-buy'?'button-primary':'button-outline'} button-small" data-ability-mode="point-buy">Point buy</button><button type="button" class="button ${builder.abilityMethod==='manual'?'button-primary':'button-outline'} button-small" data-ability-mode="manual">Manual</button></div><p class="field-hint">${builder.abilityMethod==='point-buy'?`Point buy: ${spent} / 27 points spent · ${27-spent} remaining. Scores must stay between 8 and 15.`:builder.abilityMethod==='standard'?'Standard array: 15, 14, 13, 12, 10, 8. You can switch to manual to customize.':'Manual mode: set base scores from 3 to 20.'}</p>${renderASIChoices()}<div class="ability-grid">${Object.entries(builder.abilities).map(([k,v])=>{const b=bonus[k.toLowerCase()]||0;return `<label class="ability-card"><span>${k}</span><input type="number" min="${builder.abilityMethod==='point-buy'?8:3}" max="${builder.abilityMethod==='point-buy'?15:20}" value="${v}" data-ability="${k}" ${builder.abilityMethod==='standard'?'readonly':''}><small>Base ${v} ${b?`+ ${b} bonus = ${v+b}`:''} · Mod ${Math.floor((v+b-10)/2)>=0?'+':''}${Math.floor((v+b-10)/2)}</small></label>`;}).join('')}</div><div class="ability-presets"><span>Bonuses: ${Object.entries(bonus).filter(([,v])=>v).map(([k,v])=>`${k.toUpperCase()} +${v}`).join(' · ')||'None applied'}</span></div></div>`;}
 if(key==='background'){const bg=builderBackground();return `${builderChoices('backgrounds',builder.backgroundId?[builder.backgroundId]:[])}${bg?`<div class="builder-rule-card"><div class="eyebrow">BACKGROUND BENEFITS</div><h3>${esc(bg.name)}</h3><p>${esc(bg.description||'')}</p><div class="tag-list">${(bg.skillProficiencies||[]).map(x=>`<span>${esc(x)} proficiency</span>`).join('')}${bg.feat?.featId?`<span>Feat: ${esc(bg.feat.featId)}</span>`:''}${(bg.abilityScores||[]).map(x=>`<span>Ability choice: ${esc(x.toUpperCase())}</span>`).join('')}</div></div>`:''}`;}
 if(key==='skills') return renderBuilderSkills();
 if(key==='feats') return renderBuilderFeats();
 if(key==='equipment') return renderBuilderEquipment();
 if(key==='spells') return renderBuilderSpells();
 if(key==='details') return `<div class="form-grid"><label class="form-field"><span>CHARACTER NAME</span><input id="builderName" value="${esc(builder.name)}" placeholder="e.g. Elara Nightbloom" required></label><label class="form-field"><span>LEVEL</span><input id="builderLevel" type="number" min="1" max="20" value="${builder.level}"></label><label class="form-field full"><span>CHARACTER NOTES</span><textarea id="builderNotes" rows="4" placeholder="Personality, goals, allies, backstory…">${esc(builder.notes)}</textarea></label></div><div class="build-summary">${buildSummary()}</div>`;
 return '';
}
function buildSummary(){const cls=builderClass(),race=builderRace(),bg=builderBackground();return `<div><span>CLASS</span><b>${esc(nameOf(cls||{}))}</b></div><div><span>SPECIES</span><b>${esc(nameOf(race||{}))}${builderSubrace()?` · ${esc(builderSubrace().name)}`:''}</b></div><div><span>BACKGROUND</span><b>${esc(nameOf(bg||{}))}</b></div><div><span>SKILLS / FEATS / SPELLS</span><b>${builder.skills.length+fixedBackgroundSkills().length+builder.backgroundSkills.flat().length} / ${grantedFeatRecords().length+builder.feats.length} / ${builder.spells.length}</b></div>`;}
function renderBuilder(){const step=BUILDER_STEPS[builder.step];return `${pageShell('GUIDED CHARACTER CREATION','Forge your <em>character.</em>','A guided path through class, species, background, proficiencies, equipment, and spells.',`<button class="button button-quiet" data-go="characters">Cancel</button>`)}<div class="builder-layout"><aside class="panel builder-steps"><div class="eyebrow">BUILD PROGRESS</div><div class="progress-track"><span style="width:${(builder.step+1)/BUILDER_STEPS.length*100}%"></span></div>${BUILDER_STEPS.map((s,i)=>`<button type="button" class="builder-step ${i===builder.step?'active':''} ${i<builder.step?'done':''}" data-step="${i}" aria-current="${i===builder.step?'step':'false'}"><span>${i<builder.step?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${s[1]}</strong><small>${s[2]}</small></span></button>`).join('')}<div class="builder-rules-note">RULESET <strong>${activeEdition}</strong><small>Selection indicators follow the active step. Choices are restricted by your selected class, species, and background.</small></div></aside><section class="panel builder-stage"><div class="builder-stage-head"><div><div class="eyebrow">STEP ${String(builder.step+1).padStart(2,'0')} OF 10</div><h2>${step[1]}</h2><p>${step[2]}</p></div><span class="edition-chip">D&D ${activeEdition}</span></div><div class="builder-step-content" id="builderStepContent">${stepContent({key:step[0]})}</div><div class="builder-actions"><button class="button button-outline" data-builder-prev ${builder.step===0?'disabled':''}>← Previous</button><span class="step-counter">${builder.step+1} / ${BUILDER_STEPS.length}</span>${builder.step===BUILDER_STEPS.length-1?'<button class="button button-primary" data-save-character>Save character ✦</button>':'<button class="button button-primary" data-builder-next>Continue →</button>'}</div></section></div>`;}
function renderBuilderStep(){const el=$('#builderStepContent');if(el)el.innerHTML=stepContent({key:BUILDER_STEPS[builder.step][0]});const actions=$('.builder-actions');if(actions)actions.innerHTML=`<button class="button button-outline" data-builder-prev ${builder.step===0?'disabled':''}>← Previous</button><span class="step-counter">${builder.step+1} / ${BUILDER_STEPS.length}</span>${builder.step===BUILDER_STEPS.length-1?'<button class="button button-primary" data-save-character>Save character ✦</button>':'<button class="button button-primary" data-builder-next>Continue →</button>'}`;const aside=$('.builder-steps');if(aside){aside.querySelectorAll('.builder-step').forEach((n,i)=>{n.classList.toggle('active',i===builder.step);n.classList.toggle('done',i<builder.step);n.setAttribute('aria-current',i===builder.step?'step':'false');});const bar=aside.querySelector('.progress-track span');if(bar)bar.style.width=`${(builder.step+1)/BUILDER_STEPS.length*100}%`;}const h=$('.builder-stage-head');if(h){h.querySelector('.eyebrow').textContent=`STEP ${String(builder.step+1).padStart(2,'0')} OF 10`;h.querySelector('h2').textContent=BUILDER_STEPS[builder.step][1];h.querySelector('p').textContent=BUILDER_STEPS[builder.step][2];}}
function resolveSelected(category,ids){return ids.map(id=>findRecord(category,id)).filter(Boolean);}
function resolveEquipmentChoices(){const out=[];for(const [owner,groups] of [[`class-${builder.classId}`,builderClass()?.startingEquipmentOptions||[]],[`background-${builder.backgroundId}`,builderBackground()?.equipmentOptions||[]]]){for(let i=0;i<groups.length;i++){const g=groups[i],key=g.id||`${owner}-${i}`,opts=g.options||[];if(!opts.length)continue;const selected=builder.equipmentChoices[key]??String(opts[0].key??0);const option=opts.find((o,j)=>String(o.key??j)===String(selected))||opts[0];for(const item of (option.items||[]))out.push({...item,source:owner.startsWith('class-')?'Class starting equipment':'Background equipment',choiceGroup:key,choiceLabel:option.label||option.key||'Included'});if(option.gold)out.push({name:`${option.gold} gp`,kind:'currency',quantity:1,source:owner.startsWith('class-')?'Class starting equipment':'Background equipment',choiceGroup:key});}}return out;}
function derivedArmorClass(cls,gear,abilities,bonuses){const dex=Math.floor((Number(abilities.DEX||10)+Number(bonuses.dex||0)-10)/2),con=Math.floor((Number(abilities.CON||10)+Number(bonuses.con||0)-10)/2),wis=Math.floor((Number(abilities.WIS||10)+Number(bonuses.wis||0)-10)/2);const items=gear.map(g=>findRecord('items',g.itemId||g.name)).filter(Boolean);const armor=items.find(x=>x.kind==='armor');const shield=items.some(x=>x.kind==='shield');let ac;if(armor){ac=Number(armor.baseAc||10)+(armor.addDex?Math.min(dex,armor.maxDex==null?dex:Number(armor.maxDex)):0);}else if(String(cls?.name||'').toLowerCase()==='barbarian')ac=10+dex+con;else if(String(cls?.name||'').toLowerCase()==='monk')ac=10+dex+wis;else ac=10+dex;if(shield)ac+=2;return Math.max(10,ac);}
function saveCharacter(){const name=$('#builderName')?.value.trim()||builder.name||'Unnamed Adventurer';builder.name=name;builder.level=Math.max(1,Math.min(20,Number($('#builderLevel')?.value||builder.level||1)));builder.notes=$('#builderNotes')?.value||builder.notes;const cls=builderClass(),race=builderRace(),bg=builderBackground();const grants=grantedFeatRecords().map(({__grantSource,...f})=>({...f,grantSource:__grantSource}));const chosenFeats=resolveSelected('feats',builder.feats);const allFeats=[...grants,...chosenFeats.filter(f=>!grants.some(g=>idOf(g)===idOf(f)))];const bonuses=abilityBonuses(),startingGear=resolveEquipmentChoices();const conMod=Math.floor((Number(builder.abilities.CON||10)+Number(bonuses.con||0)-10)/2),hitDie=Number(cls?.hitDie||8),hp=Math.max(1,hitDie+conMod+Math.max(0,builder.level-1)*(Math.floor(hitDie/2)+1+conMod)),ac=derivedArmorClass(cls,startingGear,builder.abilities,bonuses);const ch={id:crypto.randomUUID?crypto.randomUUID():`char-${Date.now()}`,name,edition:activeEdition,level:builder.level,classId:builder.classId,className:nameOf(cls||{}),raceId:builder.raceId,speciesName:nameOf(race||{}),subraceId:builder.subraceId,subraceName:builderSubrace()?.name||'',subclassId:builder.subclassId,subclassName:subclassesForCurrentClass().find(x=>idOf(x)===builder.subclassId)?.name||'',backgroundId:builder.backgroundId,backgroundName:nameOf(bg||{}),abilities:{...builder.abilities},abilityBonuses:bonuses,skills:[...new Set([...fixedBackgroundSkills(),...builder.backgroundSkills.flat(),...builder.skills])],backgroundSkillChoices:builder.backgroundSkills.map(x=>[...x]),feats:allFeats,equipmentChoices:{...builder.equipmentChoices},equipment:[...startingGear,...resolveSelected('items',builder.equipment)],spells:resolveSelected('spells',builder.spells),hp,maxHp:hp,ac,notes:builder.notes,createdAt:new Date().toISOString()};state.characters.push(ch);state.selectedCharacterId=ch.id;selectedCharacterId=ch.id;saveState();builder=freshBuilder();toast('Character saved to your local vault.');go('sheet');}
function renderSheet(){const c=state.characters.find(x=>x.id===(selectedCharacterId||state.selectedCharacterId));if(!c)return `${pageShell('PLAYER STUDIO','Character <em>sheet.</em>','Open a saved character to view its details and selected content.')}<div class="empty-large"><div class="empty-emblem">▤</div><h2>No character <em>selected.</em></h2><p>Create a character or open one from your character vault.</p><button class="button button-primary" data-go="builder">Create character</button><button class="button button-outline" data-go="characters">My characters</button></div>`;return `${pageShell('ADVENTURER RECORD',`${esc(c.name)} <em>the adventurer.</em>`,'Your character choices, abilities, and selected content in one place.',`<button class="button button-outline" data-export-character="${esc(c.id)}">Export JSON</button><button class="button button-primary" data-edit-character="${esc(c.id)}">Edit build</button>`)}<div class="sheet-hero"><div class="sheet-avatar">${esc(c.name.slice(0,1).toUpperCase())}</div><div class="sheet-identity"><div class="eyebrow">D&D ${esc(c.edition)} · LEVEL ${c.level}</div><h2>${esc(c.name)}</h2><p>${esc(c.speciesName)} · ${esc(c.className)}${c.subclassName?` · ${esc(c.subclassName)}`:''}</p></div><div class="sheet-vitals"><div><span>HIT POINTS</span><b>${c.hp??10}<small> / ${c.maxHp??10}</small></b></div><div><span>ARMOR CLASS</span><b>${c.ac??10}</b></div></div></div><div class="sheet-grid"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">ABILITY SCORES</div><h3>Core attributes</h3></div></div><div class="ability-grid sheet-abilities">${Object.entries(c.abilities||{}).map(([k,v])=>{const total=Number(v)+(Number(c.abilityBonuses?.[k.toLowerCase()]||0));const mod=Math.floor((total-10)/2);return `<div class="ability-card"><span>${esc(k)}</span><b>${total}</b><small>Base ${v} · ${mod>=0?'+':''}${mod}</small></div>`;}).join('')}</div></section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">CHARACTER DETAILS</div><h3>Background & skills</h3></div></div><p><strong>${esc(c.backgroundName||'No background selected')}</strong></p><div class="tag-list">${(c.skills||[]).map(s=>`<span>${esc(s)}</span>`).join('')||'<small>No skills selected.</small>'}</div><p class="muted-copy">${esc(c.notes||'No personal notes yet.')}</p></section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">CLASS REFERENCE</div><h3>Class progression</h3></div></div>${(()=>{const cl=findRecord('classes',c.classId,c.edition||activeEdition);return cl?`<p class="muted-copy">${esc(cl.description||'')}</p><div class="tag-list"><span>Hit Die: ${esc(cl.hitDie||'—')}</span><span>Subclass at level ${esc(cl.subclassLevel||'—')}</span></div><button class="button button-outline button-small" data-detail-inline="${esc(idOf(cl))}" data-detail-category="classes" data-detail-edition="${esc(c.edition||activeEdition)}">View full class record</button>`:'<p class="muted-copy">Class record not found in the selected ruleset.</p>';})()}</section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">KNOWN SPELLS</div><h3>Spellbook <small>${(c.spells||[]).length}</small></h3></div></div>${renderSelectedList(c.spells,'spells',c.edition)}</section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">PACK & GEAR</div><h3>Equipment <small>${(c.equipment||[]).length}</small></h3></div></div>${c.equipment?.length?`<div class="selected-list">${c.equipment.map(x=>`<div><strong>${esc(x.name||x.label||'Equipment')}</strong><small>${esc(x.source||x.kind||'')}${x.quantity>1?` · ×${x.quantity}`:''}</small></div>`).join('')}</div>`:renderSelectedList([], 'items', c.edition)}</section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">TALENTS</div><h3>Feats <small>${(c.feats||[]).length}</small></h3></div></div>${renderSelectedList(c.feats,'feats',c.edition)}</section></div>`;}
function renderSelectedList(items=[],category='',edition=activeEdition){return items.length?`<div class="selected-list">${items.map(x=>`<button data-detail-inline="${esc(idOf(x))}" data-detail-category="${category}" data-detail-edition="${edition}"><strong>${esc(nameOf(x))}</strong><small>${esc(shortText(x.description||x.source||'',90))}</small></button>`).join('')}</div>`:'<div class="empty-state compact">Nothing selected yet.</div>';}
function renderHomebrew(){const groups=[['classes','Class'],['subclasses','Subclass'],['races','Species / race'],['backgrounds','Background'],['feats','Feat'],['spells','Spell'],['items','Equipment'],['magicitems','Magic item'],['masteries','Weapon mastery']];return `${pageShell('CREATOR STUDIO','Homebrew <em>workshop.</em>','Create original content for your table. Homebrew is stored separately from the supplied ruleset JSON.',`<button class="button button-primary" data-action="new-homebrew">＋ Create content</button>`)}<div class="homebrew-intro"><div><span class="feature-kicker">YOUR CREATIONS, YOUR RULES</span><h2>Make something that<br><em>has never existed.</em></h2><p>Homebrew entries live in your local workspace. They never overwrite or modify the original 2014 or 2024 content files.</p></div><div class="homebrew-stat"><strong>${state.homebrew.length}</strong><span>YOUR CREATIONS</span></div></div><div class="homebrew-category-grid">${groups.map(([k,label])=>`<button class="homebrew-category" data-new-kind="${k}"><span>${CATEGORIES.find(x=>x[0]===k)?.[2]||'✦'}</span><strong>${label}</strong><small>Create a custom ${label.toLowerCase()} entry</small><b>＋</b></button>`).join('')}</div><section class="panel homebrew-entries"><div class="panel-heading"><div><div class="eyebrow">PERSONAL CONTENT</div><h3>Your homebrew library</h3></div><button class="text-button" data-action="export-homebrew">Export JSON ↗</button></div>${state.homebrew.length?`<div class="homebrew-list">${state.homebrew.map((h,i)=>`<div class="homebrew-row"><span class="homebrew-glyph">${CATEGORIES.find(x=>x[0]===h.kind)?.[2]||'✦'}</span><span><strong>${esc(h.name)}</strong><small>${esc(titleCase(h.kind))} · ${esc(h.source||'Homebrew')}</small></span><button class="text-button" data-view-homebrew="${esc(h.id)}">View</button><button class="icon-button danger-icon" data-delete-homebrew="${esc(h.id)}">×</button></div>`).join('')}</div>`:'<div class="empty-state compact">No homebrew created yet. Choose a content type above to start.</div>'}</section>`;}
function renderLibrary(){return `${pageShell('REFERENCE LIBRARY','The content <em>compendium.</em>','Browse the imported data exactly as supplied, with full descriptions and structured fields.',`<span class="edition-chip">${activeEdition} RULESET</span>`)}<section class="panel library-panel"><div class="library-toolbar"><label class="catalog-search"><span>⌕</span><input id="librarySearch" type="search" value="${esc(libraryQuery)}" placeholder="Search names, descriptions, features, prerequisites…"></label><label class="select-label">CATEGORY<select id="libraryCategory">${[['all','All content','✦'],...CATEGORIES].map(([k,l])=>`<option value="${k}" ${libraryCategory===k?'selected':''}>${l}</option>`).join('')}</select></label><span class="record-count" id="libraryCount"></span></div><div class="library-layout"><div><div class="library-grid" id="libraryGrid"></div><div class="pagination" id="libraryPagination"></div></div><aside class="catalog-aside"><div class="aside-emblem">◈</div><div class="eyebrow">SOURCE DATA</div><h3>Read the full record.</h3><p>Each entry is loaded directly from the selected JSON file. Nested features, traits, level tables, spell details, prices, prerequisites, and other fields are preserved.</p><div class="aside-meta"><span>EDITION</span><b>${activeEdition}</b></div><div class="aside-meta"><span>FILE</span><b id="activeDataFile">${activeEdition}/${libraryCategory}.json</b></div><div class="aside-meta"><span>RECORDS</span><b id="asideRecordCount">—</b></div><button class="button button-outline button-full" data-action="export-catalog">Download this JSON</button></aside></div></section>`;}
function subclassRecords(){const output=[];for(const cls of records(activeEdition,'classes')){(cls.subclasses||[]).forEach((s,i)=>{const x=typeof s==='string'?{name:s,description:''}:s;output.push({...x,__className:cls.name,id:x.id||`${cls.id||cls.name}-sub-${i}`});});}return output;}
function librarySource(){if(libraryCategory==='all')return CATEGORIES.filter(([k])=>k!=='all').flatMap(([k])=>{const source=k==='subclasses'?subclassRecords():k==='monsters'?records('2014','monsters'):records(activeEdition,k);return source.map(x=>({...x,__category:k}));});if(libraryCategory==='subclasses')return subclassRecords();if(libraryCategory==='monsters')return records('2014','monsters');return records(activeEdition,libraryCategory);}
function renderLibraryList(){const grid=$('#libraryGrid');if(!grid)return;const source=librarySource();const q=libraryQuery.trim().toLowerCase();const filtered=q?source.filter(x=>JSON.stringify(x).toLowerCase().includes(q)):source;const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));libraryPage=Math.min(libraryPage,pages);const start=(libraryPage-1)*PAGE_SIZE;const items=filtered.slice(start,start+PAGE_SIZE);$('#libraryCount').textContent=`${filtered.length.toLocaleString()} records`;$('#asideRecordCount').textContent=source.length.toLocaleString();$('#activeDataFile').textContent=libraryCategory==='all'?'all selected JSON files':libraryCategory==='subclasses'?'classes.json → subclasses':libraryCategory==='monsters'?'catalogs/monsters.json':`${activeEdition}/${libraryCategory}.json`;grid.innerHTML=items.length?items.map((x,i)=>`<button class="library-card" data-record-index="${start+i}"><span class="library-card-top"><span>${CATEGORIES.find(c=>c[0]===libraryCategory)?.[2]||'✦'}</span><small>${esc(x.source||x.category||x.kind||libraryCategory)}</small></span><strong>${esc(nameOf(x))}</strong><p>${esc(shortText(x.description||x.prerequisite||x.rarity||x.school||x.category||x.kind||x.__className||'Open record to inspect all fields.',130))}</p><b>View full entry ↗</b></button>`).join(''):'<div class="empty-state">No records match this search.</div>';$('#libraryPagination').innerHTML=`<span>Showing ${filtered.length?start+1:0}–${Math.min(start+PAGE_SIZE,filtered.length)} of ${filtered.length}</span><div><button class="button button-outline button-small" data-library-page="-1" ${libraryPage===1?'disabled':''}>←</button><span>${libraryPage} / ${pages}</span><button class="button button-outline button-small" data-library-page="1" ${libraryPage===pages?'disabled':''}>→</button></div>`;grid.dataset.total=filtered.length;grid.dataset.start=start;grid._items=items;}
function valueMarkup(value,depth=0){if(value===null||value===undefined||value==='')return '<span class="muted-copy">—</span>';if(typeof value==='boolean')return `<span class="boolean-chip ${value?'yes':'no'}">${value?'Yes':'No'}</span>`;if(typeof value==='number')return `<span class="number-value">${value}</span>`;if(typeof value==='string')return `<p class="detail-text">${esc(value).replace(/\n/g,'<br>')}</p>`;if(Array.isArray(value)){if(!value.length)return '<span class="muted-copy">Empty list</span>';return `<div class="detail-array">${value.map(v=>typeof v==='object'&&v!==null?`<div class="nested-record">${valueMarkup(v,depth+1)}</div>`:`<span class="detail-tag">${esc(String(v))}</span>`).join('')}</div>`;}if(typeof value==='object'){const entries=Object.entries(value);if(depth>3)return `<pre class="json-block">${esc(JSON.stringify(value,null,2))}</pre>`;return `<div class="detail-object">${entries.map(([k,v])=>`<div class="detail-field"><span>${esc(titleCase(k))}</span><div>${valueMarkup(v,depth+1)}</div></div>`).join('')}</div>`;}return esc(String(value));}
function showDetail(item,category){currentDetail={item,category};const keys=Object.keys(item).filter(k=>!k.startsWith('__'));$('#detailDialogContent').innerHTML=`<div class="detail-kind">${esc(titleCase(category))} · D&D ${esc(activeEdition)}</div><h2>${esc(nameOf(item))}</h2><div class="detail-source">${esc(item.source||item.__className||'Imported JSON record')}</div><div class="detail-fields">${keys.map(k=>`<section class="record-field"><h4>${esc(titleCase(k))}</h4>${valueMarkup(item[k])}</section>`).join('')}</div><div class="detail-actions"><button class="button button-outline" data-action="copy-record">Copy JSON</button><button class="button button-primary" data-action="add-to-homebrew" data-record-name="${esc(nameOf(item))}">Use as homebrew draft</button></div>`;$('#detailDialog').showModal();}
function renderTable(){return `${pageShell('AT THE TABLE','DM toolkit <em>& encounter desk.</em>','A compact session utility. Player Studio remains the main workspace; connect Owlbear when you are ready to sync tokens.',`<button class="button button-primary" data-action="add-combatant">＋ Add combatant</button>`)}<div class="table-toolbar"><div class="round-control"><span>ROUND</span><button data-round="-1">−</button><b id="roundNumber">${state.round||1}</b><button data-round="1">＋</button></div><button class="button button-outline" data-action="next-turn">Next turn →</button><span class="edition-chip" id="obrState">Standalone mode</span></div><section class="panel combat-table-panel"><div class="combat-table-head"><span>INIT</span><span>COMBATANT</span><span>HIT POINTS</span><span>ARMOR CLASS</span><span></span></div><div id="combatantList">${renderCombatantRows()}</div></section><div class="bottom-note"><span>✦</span><span>Combat state is stored locally in this browser in this prototype. Owlbear room synchronisation is a separate integration step.</span></div>`;}
function renderCombatantRows(){return state.combatants.length?[...state.combatants].sort((a,b)=>b.initiative-a.initiative).map((x,i)=>`<div class="combatant-row"><b>${x.initiative}</b><span class="combat-name-cell"><span class="combat-avatar ${x.side==='enemy'?'enemy':'player'}">${x.side==='enemy'?'♟':'♙'}</span><span><strong>${esc(x.name)}</strong><small>${esc(x.kind||x.side||'Adventurer')}</small></span></span><span class="hp-value">${x.hp}/${x.maxHp}</span><span>${x.ac||'—'}</span><button class="icon-button danger-icon" data-remove-combatant="${esc(x.id)}">×</button></div>`).join(''):'<div class="empty-state">No combatants yet. Add characters or NPCs when the encounter begins.</div>';}
function renderDice(){return `${pageShell('TABLE TOOLS','Roll the <em>fateful dice.</em>','A quick dice roller for checks, saves, damage, and whatever the story demands.')}<div class="dice-layout"><section class="panel dice-stage"><div class="eyebrow">ROLL A CHECK</div><div class="dice-big-result" id="diceResult">—</div><div class="dice-expression-row"><input id="diceExpression" value="1d20+3" aria-label="Dice expression"><button class="button button-primary" data-action="roll-dice">Roll dice ⚄</button></div><div class="dice-quick-picks">${[4,6,8,10,12,20,100].map(x=>`<button data-quick-die="${x}">d${x}</button>`).join('')}</div><div id="diceLastRoll" class="dice-last-roll">Use expressions like 2d20+5, 4d6kh3, or 1d8+2.</div></section><aside class="panel dice-history"><div class="panel-heading"><div><div class="eyebrow">ROLL HISTORY</div><h3>Recent rolls</h3></div><button class="text-button" data-action="clear-rolls">Clear</button></div><div id="diceHistory">${renderDiceHistory()}</div></aside></div>`;}
function renderDiceHistory(){return state.diceHistory.length?`<div class="dice-history-list">${state.diceHistory.slice(0,20).map(x=>`<div class="history-row"><span>${esc(x.expression)}</span><b>${x.total}</b><small>${esc(x.detail)}</small></div>`).join('')}</div>`:'<div class="empty-state compact">Your rolls will appear here.</div>';}
function renderSettings(){return `${pageShell('WORKSPACE PREFERENCES','Settings <em>& data.</em>','Choose your ruleset and back up your local characters and custom content.')}<div class="settings-grid"><section class="panel settings-panel"><div class="eyebrow">RULESET</div><h3>Content edition</h3><p>Switch between the two imported datasets. Original data files are read directly and are never modified.</p><div class="edition-options"><button class="edition-option ${activeEdition==='2014'?'active':''}" data-set-edition="2014"><strong>D&D 5e · 2014</strong><small>7 source files</small></button><button class="edition-option ${activeEdition==='2024'?'active':''}" data-set-edition="2024"><strong>D&D 5e · 2024</strong><small>8 source files, including masteries</small></button></div></section><section class="panel settings-panel"><div class="eyebrow">BACKUP & RESTORE</div><h3>Your local workspace</h3><p>Characters, homebrew, combat state, and roll history stay in this browser unless you export them.</p><div class="settings-actions"><button class="button button-primary" data-action="export-all">Export workspace JSON</button><button class="button button-outline" data-action="import-workspace">Import workspace JSON</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></section><section class="panel settings-panel"><div class="eyebrow">DATA MANIFEST</div><h3>Imported content files</h3><div class="file-summary">${EDITIONS.map(ed=>`<div><b>${ed}</b><span>${DB_FILES.filter(f=>!(f==='masteries'&&ed==='2014')).map(f=>`${f}.json`).join(' · ')}</span></div>`).join('')}<div><b>Extra</b><span>catalogs/monsters.json (scraped name and URL index)</span></div></div><p class="field-hint">JSON files are kept in their original structure. No manual re-entry, conversion, or field-by-field editing is required.</p></section><section class="panel settings-panel"><div class="eyebrow">RUNTIME</div><h3>Standalone & Owlbear</h3><p id="runtimeDescription">This app runs as a standalone static website. It can also be loaded as an Owlbear extension using manifest.json.</p><div class="settings-row"><span>Owlbear SDK</span><b id="sdkStatus">Not connected</b></div><a class="doc-link" href="https://docs.owlbear.rodeo/extensions/getting-started/" target="_blank" rel="noreferrer">Owlbear extension documentation ↗</a></section></div>`;}
function openHomebrewDialog(kind='spells',seed=null){const label=CATEGORIES.find(x=>x[0]===kind)?.[1]||titleCase(kind);const defaults=seed?JSON.stringify(seed,null,2):'{\n  "source": "Homebrew",\n  "description": "",\n  "notes": ""\n}';$('#formDialogContent').innerHTML=`<div class="detail-kind">HOMEBREW EDITOR</div><h2>Create ${esc(label.toLowerCase())}</h2><p class="muted-copy">This creates a separate custom entry in your local homebrew library. The imported JSON stays untouched.</p><form id="homebrewForm" class="form-grid"><label class="form-field"><span>CONTENT TYPE</span><select name="kind">${CATEGORIES.filter(x=>x[0]!=='monsters').map(([k,l])=>`<option value="${k}" ${kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="form-field"><span>NAME</span><input name="name" required value="${esc(seed?.name||'')}" placeholder="Enter a name"></label><label class="form-field full"><span>DESCRIPTION</span><textarea name="description" rows="3">${esc(seed?.description||'')}</textarea></label><label class="form-field full"><span>ADDITIONAL FIELDS (JSON)</span><textarea name="details" rows="8" spellcheck="false">${esc(defaults)}</textarea></label><div class="form-actions full"><button type="button" class="button button-outline" data-close-dialog>Cancel</button><button class="button button-primary" type="submit">Save homebrew</button></div></form>`;$('#formDialog').showModal();}
function addHomebrew(form){const fd=new FormData(form);let details={};try{details=JSON.parse(fd.get('details')||'{}');if(!details||Array.isArray(details)||typeof details!=='object')throw new Error('JSON must be an object');}catch(e){toast(`Additional fields JSON is invalid: ${e.message}`,'warn');return;}const entry={...details,id:crypto.randomUUID?crypto.randomUUID():`hb-${Date.now()}`,kind:String(fd.get('kind')),name:String(fd.get('name')).trim(),description:String(fd.get('description')||''),source:details.source||'Homebrew',createdAt:new Date().toISOString()};if(!entry.name){toast('Name is required.','warn');return;}state.homebrew.push(entry);saveState();$('#formDialog').close();toast('Homebrew saved locally.');go('homebrew');}
function downloadFile(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
function exportWorkspace(){downloadFile('tablekeep-workspace.json',JSON.stringify({version:3,exportedAt:new Date().toISOString(),characters:state.characters,homebrew:state.homebrew,combatants:state.combatants,diceHistory:state.diceHistory},null,2));}
function exportSingleCharacter(id){const c=state.characters.find(x=>x.id===id);if(c)downloadFile(`${c.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'character'}.json`,JSON.stringify(c,null,2));}
function exportCatalog(){const data=librarySource();downloadFile(`tablekeep-${activeEdition}-${libraryCategory}.json`,JSON.stringify(data,null,2));}
function rollDice(expr){const m=String(expr).trim().match(/^(\d{1,2})d(4|6|8|10|12|20|100)([+-]\d+)?$/i);if(!m)return null;const count=Number(m[1]),sides=Number(m[2]),mod=Number(m[3]||0);if(count<1||count>50)return null;const rolls=Array.from({length:count},()=>1+Math.floor(Math.random()*sides));return {total:rolls.reduce((a,b)=>a+b,0)+mod,detail:`${rolls.join(' + ')}${mod?` ${mod>0?'+':''}${mod}`:''}`,expression:expr};}
function setEdition(ed){if(!EDITIONS.includes(ed))return;activeEdition=ed;state.edition=ed;saveState();$('#globalEdition').value=ed;if(activePage==='library'){libraryPage=1;go('library');}else if(activePage==='builder'){go('builder');}else go('home');toast(`D&D ${ed} content loaded.`);}
function handleClick(e){
 const goBtn=e.target.closest('[data-go],[data-page]');if(goBtn){go(goBtn.dataset.go||goBtn.dataset.page);return;}
 const cat=e.target.closest('[data-library]');if(cat){libraryCategory=cat.dataset.library;libraryQuery='';go('library');return;}
 const step=e.target.closest('[data-step]');if(step){builder.step=Number(step.dataset.step);renderBuilderStep();return;}
 if(e.target.closest('[data-builder-next]')){if(builder.step<9){if(builder.step===0&&!builder.classId&&records(activeEdition,'classes')[0])builder.classId=idOf(records(activeEdition,'classes')[0]);if(builder.step===1&&!builder.raceId&&records(activeEdition,'races')[0])builder.raceId=idOf(records(activeEdition,'races')[0]);if(builder.step===3&&builder.abilityMethod==='point-buy'&&(pointBuySpent()>27||Object.values(builder.abilities).some(v=>v<8||v>15))){toast('Point buy must use no more than 27 points and scores from 8 to 15.','warn');return;}builder.step++;renderBuilderStep();}return;}
 if(e.target.closest('[data-builder-prev]')){builder.step=Math.max(0,builder.step-1);renderBuilderStep();return;}
 if(e.target.closest('[data-ability-mode]')){const mode=e.target.closest('[data-ability-mode]').dataset.abilityMode;builder.abilityMethod=mode;if(mode==='standard')builder.abilities={STR:15,DEX:14,CON:13,INT:12,WIS:10,CHA:8};if(mode==='point-buy')builder.abilities={STR:8,DEX:8,CON:8,INT:8,WIS:8,CHA:8};renderBuilderStep();return;}
 if(e.target.closest('[data-save-character]')){saveCharacter();return;}
 const grantChoice=e.target.closest('[data-granted-feat]');if(grantChoice){builder.grantedFeats[grantChoice.dataset.grantedFeat]=grantChoice.dataset.id;renderBuilderStep();return;}
 const choice=e.target.closest('[data-choice]');if(choice){const {choice:kind,id}=choice.dataset;if(kind==='classes'){builder.classId=id;builder.subclassId='';builder.skills=[];builder.backgroundSkills=[];builder.spells=[];builder.equipmentChoices={};}else if(kind==='races'){builder.raceId=id;builder.subraceId='';builder.asiChoices.race=[];builder.grantedFeats={};}else if(kind==='subraces'){builder.subraceId=builder.subraceId===id?'':id;builder.asiChoices.race=[];builder.grantedFeats={};}else if(kind==='backgrounds'){builder.backgroundId=id;builder.equipmentChoices={};builder.asiChoices.background=[];builder.backgroundSkills=[];builder.grantedFeats={};builder.skills=builder.skills.filter(x=>!fixedBackgroundSkills().includes(x));}else if(kind==='subclasses')builder.subclassId=builder.subclassId===id?'':id;else{const prop=({feats:'feats',items:'equipment',spells:'spells'})[kind];if(prop){const arr=builder[prop];if(kind==='spells'&&!arr.includes(id)){const spell=findRecord('spells',id),limits=spellLimits();const cantrips=arr.filter(x=>findRecord('spells',x)?.level===0).length,leveled=arr.filter(x=>(findRecord('spells',x)?.level||0)>0).length;if(spell?.level===0&&limits.cantrips!==null&&cantrips>=limits.cantrips){toast(`Your class can learn ${limits.cantrips} cantrip(s) at this level.`,'warn');return;}if(spell?.level>0&&limits.known!==null&&leveled>=limits.known){toast(`Your class allowance is ${limits.known} known/prepared spell(s) at this level.`,'warn');return;}}builder[prop]=arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];}}renderBuilderStep();return;}
 const record=e.target.closest('[data-record-index]');if(record){const source=librarySource();const q=libraryQuery.trim().toLowerCase();const filtered=q?source.filter(x=>JSON.stringify(x).toLowerCase().includes(q)):source;const item=filtered[Number(record.dataset.recordIndex)];if(item)showDetail(item,item.__category||libraryCategory);return;}
 const openChar=e.target.closest('[data-open-character]');if(openChar){selectedCharacterId=openChar.dataset.openCharacter;state.selectedCharacterId=selectedCharacterId;saveState();go('sheet');return;}
 const delChar=e.target.closest('[data-delete-character]');if(delChar){if(confirm('Delete this character from your local vault?')){state.characters=state.characters.filter(x=>x.id!==delChar.dataset.deleteCharacter);saveState();go('characters');}return;}
 const editChar=e.target.closest('[data-edit-character]');if(editChar){const c=state.characters.find(x=>x.id===editChar.dataset.editCharacter);if(c){builder={...freshBuilder(),name:c.name,level:c.level||1,classId:c.classId||'',raceId:c.raceId||'',subclassId:c.subclassId||'',backgroundId:c.backgroundId||'',abilities:{STR:10,DEX:10,CON:10,INT:10,WIS:10,CHA:10,...c.abilities},skills:c.skills||[],feats:(c.feats||[]).map(idOf),equipment:(c.equipment||[]).map(idOf),spells:(c.spells||[]).map(idOf),notes:c.notes||''};state.characters=state.characters.filter(x=>x.id!==c.id);saveState();go('builder');}return;}
 const hbDel=e.target.closest('[data-delete-homebrew]');if(hbDel){state.homebrew=state.homebrew.filter(x=>x.id!==hbDel.dataset.deleteHomebrew);saveState();go('homebrew');return;}
 const hbView=e.target.closest('[data-view-homebrew]');if(hbView){const x=state.homebrew.find(h=>h.id===hbView.dataset.viewHomebrew);if(x)showDetail(x,x.kind);return;}
 const inline=e.target.closest('[data-detail-inline]');if(inline){const x=findRecord(inline.dataset.detailCategory,inline.dataset.detailInline,inline.dataset.detailEdition||activeEdition);if(x)showDetail(x,inline.dataset.detailCategory);return;}
 const hbNew=e.target.closest('[data-new-kind]');if(hbNew){openHomebrewDialog(hbNew.dataset.newKind);return;}
 if(e.target.closest('[data-action="new-homebrew"]')){openHomebrewDialog();return;}
 if(e.target.closest('[data-action="export-homebrew"]')){downloadFile('tablekeep-homebrew.json',JSON.stringify(state.homebrew,null,2));return;}
 if(e.target.closest('[data-action="export-characters"]')){downloadFile('tablekeep-characters.json',JSON.stringify(state.characters,null,2));return;}
 if(e.target.closest('[data-action="import-character"]')){$('#importCharacterFile')?.click();return;}
 if(e.target.closest('[data-export-character]')){exportSingleCharacter(e.target.closest('[data-export-character]').dataset.exportCharacter);return;}
 if(e.target.closest('[data-action="export-all"]')){exportWorkspace();return;}
 if(e.target.closest('[data-action="import-workspace"]')){$('#importFile').click();return;}
 if(e.target.closest('[data-action="export-catalog"]')){exportCatalog();return;}
 if(e.target.closest('[data-action="copy-record"]')){if(currentDetail)navigator.clipboard?.writeText(JSON.stringify(currentDetail.item,null,2)).then(()=>toast('Record JSON copied.')).catch(()=>toast('Clipboard access unavailable.','warn'));return;}
 if(e.target.closest('[data-action="add-to-homebrew"]')){if(currentDetail)openHomebrewDialog(currentDetail.category,currentDetail.item);$('#detailDialog').close();return;}
 if(e.target.closest('[data-set-edition]')){setEdition(e.target.closest('[data-set-edition]').dataset.setEdition);return;}
 if(e.target.closest('[data-close-dialog]')){$('#formDialog').close();return;}
 if(e.target.closest('[data-library-page]')){libraryPage+=Number(e.target.closest('[data-library-page]').dataset.libraryPage);renderLibraryList();return;}
 if(e.target.closest('[data-action="add-combatant"]')){const name=prompt('Combatant name:');if(name){state.combatants.push({id:`c-${Date.now()}`,name,initiative:Number(prompt('Initiative:',10)||10),hp:Number(prompt('Hit points:',10)||10),maxHp:10,ac:10,side:'player'});saveState();go('table');}return;}
 if(e.target.closest('[data-remove-combatant]')){state.combatants=state.combatants.filter(x=>x.id!==e.target.closest('[data-remove-combatant]').dataset.removeCombatant);saveState();go('table');return;}
 if(e.target.closest('[data-round]')){state.round=Math.max(1,(state.round||1)+Number(e.target.closest('[data-round]').dataset.round));saveState();go('table');return;}
 if(e.target.closest('[data-action="next-turn"]')){toast('Turn advanced in this local prototype.');return;}
 if(e.target.closest('[data-action="roll-dice"]')||e.target.closest('[data-quick-die]')){const expr=e.target.closest('[data-quick-die]')?`1d${e.target.closest('[data-quick-die]').dataset.quickDie}`:$('#diceExpression').value;const result=rollDice(expr);if(!result){toast('Use a dice expression such as 2d20+5.','warn');return;}state.diceHistory.unshift(result);saveState();$('#diceResult').textContent=result.total;$('#diceLastRoll').textContent=`${result.expression}: ${result.detail} = ${result.total}`;$('#diceHistory').innerHTML=renderDiceHistory();return;}
 if(e.target.closest('[data-action="clear-rolls"]')){state.diceHistory=[];saveState();$('#diceHistory').innerHTML=renderDiceHistory();return;}
}
function bind(){document.addEventListener('click',handleClick);$('#globalEdition').value=activeEdition;$('#globalEdition').addEventListener('change',e=>setEdition(e.target.value));$('#menuToggle').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobileScrim').classList.add('show');});$('#mobileScrim').addEventListener('click',closeSidebar);$('#pageRoot').addEventListener('input',e=>{if(e.target.id==='librarySearch'){libraryQuery=e.target.value;libraryPage=1;renderLibraryList();}if(e.target.matches('[data-ability]'))builder.abilities[e.target.dataset.ability]=Number(e.target.value);if(e.target.matches('[data-builder-search]')){builder.search[e.target.dataset.builderSearch]=e.target.value;renderBuilderStep();const search=$(`[data-builder-search="${e.target.dataset.builderSearch}"]`);if(search){search.focus();search.setSelectionRange(search.value.length,search.value.length);}}if(e.target.id==='builderName')builder.name=e.target.value;if(e.target.id==='builderLevel'){builder.level=Math.max(1,Math.min(20,Number(e.target.value||1)));}if(e.target.id==='builderNotes')builder.notes=e.target.value;});$('#pageRoot').addEventListener('change',e=>{if(e.target.id==='libraryCategory'){libraryCategory=e.target.value;libraryPage=1;renderLibraryList();}if(e.target.matches('[data-builder-option]')){builder.equipmentChoices[e.target.dataset.builderOption]=e.target.value;}if(e.target.matches('[data-asi-choice]')){const group=e.target.dataset.asiChoice,limit=group==='race'?Number((builderSubrace()||builderRace())?.asiChoice?.count||0):2;let picks=builder.asiChoices[group]||[];picks=e.target.checked?[...new Set([...picks,e.target.value])]:picks.filter(x=>x!==e.target.value);if(picks.length>limit){e.target.checked=false;toast(`Choose no more than ${limit} ability scores here.`,'warn');return;}builder.asiChoices[group]=picks;renderBuilderStep();}if(e.target.matches('[data-skill]')){const v=e.target.dataset.skill;const max=skillChoicesForClass().count;const chosen=builder.skills.filter(x=>x!==v);if(e.target.checked&&chosen.length>=max){e.target.checked=false;toast(`Your class allows ${max} selected skill proficiencies.`,'warn');return;}builder.skills=e.target.checked?[...new Set([...chosen,v])]:chosen;e.target.closest('.skill-check').classList.toggle('checked',e.target.checked);const counter=$('.builder-rule-card .field-hint:last-child');if(counter)counter.textContent=`Selected from class: ${builder.skills.length} / ${max}`;}if(e.target.matches('[data-background-skill]')){const i=Number(e.target.dataset.backgroundSkill),group=backgroundSkillChoices()[i],limit=Number(group?.choose||1);let picks=builder.backgroundSkills[i]||[];picks=e.target.checked?[...new Set([...picks,e.target.value])]:picks.filter(x=>x!==e.target.value);if(picks.length>limit){e.target.checked=false;toast(`This background allows ${limit} selected skill(s) in this choice.`,'warn');return;}builder.backgroundSkills[i]=picks;builder.skills=builder.skills.filter(x=>!picks.includes(x));renderBuilderStep();}});$('#formDialog').addEventListener('submit',e=>{if(e.target.id==='homebrewForm'){e.preventDefault();addHomebrew(e.target);}});$('#pageRoot').addEventListener('change',async e=>{if(e.target.id==='importCharacterFile'){const f=e.target.files?.[0];if(!f)return;try{const raw=JSON.parse(await f.text());const input=Array.isArray(raw)?raw:(raw.characters||raw.character?[...(raw.characters||[raw.character])]:[raw]);const imported=input.filter(x=>x&&typeof x==='object'&&(x.name||x.characterName)).map(x=>({...x,id:x.id||`import-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name:x.name||x.characterName,edition:x.edition||activeEdition,level:Number(x.level||1),abilities:x.abilities||x.stats||{STR:10,DEX:10,CON:10,INT:10,WIS:10,CHA:10}}));if(!imported.length)throw new Error('No character record with a name was found.');state.characters.push(...imported);saveState();toast(`Imported ${imported.length} character${imported.length===1?'':'s'}.`);go('characters');}catch(err){toast(`Character import failed: ${err.message}`,'warn');}e.target.value='';}});document.addEventListener('change',async e=>{if(e.target?.id!=='importFile')return;const f=e.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());state.characters=obj.characters||state.characters;state.homebrew=obj.homebrew||state.homebrew;state.combatants=obj.combatants||state.combatants;state.diceHistory=obj.diceHistory||state.diceHistory;saveState();toast('Workspace imported.');go('home');}catch(err){toast(`Import failed: ${err.message}`,'warn');}e.target.value='';});$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){libraryQuery=e.target.value;libraryCategory='all';go('library');}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();}});}
async function connectOwlbear(){const requested=new URLSearchParams(location.search).get('mode')==='owlbear'||window.parent!==window;if(!requested)return;$('#connectionText').textContent='Connecting…';$('#workspaceLabel').textContent='Owlbear room';try{const sdk=await import('https://esm.sh/@owlbear-rodeo/sdk@1');owlBear=sdk.default||sdk.OBR||sdk;if(!owlBear.isAvailable){$('#connectionText').textContent='Standalone';return;}if(!owlBear.isReady)await new Promise(resolve=>{let off;off=owlBear.onReady(()=>{off?.();resolve();});});$('#connectionText').textContent='Owlbear connected';const status=$('#sdkStatus');if(status)status.textContent='SDK ready';}catch(e){console.info('Owlbear SDK unavailable; using local workspace.',e);$('#connectionText').textContent='Standalone fallback';}}
async function init(){
  try {
    bind();
    $('#pageRoot').innerHTML = renderPage(activePage);
    await loadDatabase();
    $('#pageRoot').innerHTML = renderPage(activePage);
    updateBadges();
    if (catalogLoadErrors.length) {
      console.warn('Tablekeep started with some unavailable content files:', catalogLoadErrors);
      toast(`${catalogLoadErrors.length} content file(s) could not be loaded. Check the browser console for details.`, 'warn');
    }
    await connectOwlbear();
  } catch(error) {
    console.error('Tablekeep startup failed:', error);
    $('#pageRoot').innerHTML = `<div class="empty-large"><h2>Tablekeep could not start.</h2><p>${esc(error.message)}. Check the browser console and verify the app is served from GitHub Pages or a local HTTP server.</p><button class="button button-primary" onclick="location.reload()">Try again</button></div>`;
  }
}
init();
